CREATE TABLE Users (Id int IDENTITY PRIMARY KEY, Email nvarchar(254) NOT NULL UNIQUE, DisplayName nvarchar(60) NOT NULL, PasswordSalt nvarchar(64) NOT NULL, PasswordHash nvarchar(128) NOT NULL, Role nvarchar(10) NOT NULL CHECK(Role IN ('Member','Admin')));
CREATE TABLE Topics (Id int IDENTITY PRIMARY KEY, Title nvarchar(80) NOT NULL UNIQUE, Description nvarchar(500) NOT NULL, ImagePath nvarchar(150) NOT NULL DEFAULT 'assets/topic.svg');
CREATE TABLE Lessons (Id int IDENTITY PRIMARY KEY, TopicId int NOT NULL REFERENCES Topics(Id), Title nvarchar(100) NOT NULL, Summary nvarchar(250) NOT NULL, Body nvarchar(4000) NOT NULL, CodeSample nvarchar(3000) NOT NULL DEFAULT '', Reminder nvarchar(500) NOT NULL DEFAULT '', SortOrder int NOT NULL CHECK(SortOrder BETWEEN 1 AND 99), PrerequisiteId int NULL REFERENCES Lessons(Id));
CREATE TABLE Questions (Id int IDENTITY PRIMARY KEY, TopicId int NOT NULL REFERENCES Topics(Id), Prompt nvarchar(300) NOT NULL, OptionA nvarchar(200) NOT NULL, OptionB nvarchar(200) NOT NULL, OptionC nvarchar(200) NOT NULL, OptionD nvarchar(200) NOT NULL, CorrectOption char(1) NOT NULL CHECK(CorrectOption IN ('A','B','C','D')));
CREATE TABLE Progress (Id int IDENTITY PRIMARY KEY, UserId int NOT NULL REFERENCES Users(Id), LessonId int NOT NULL REFERENCES Lessons(Id), Confidence int NOT NULL CHECK(Confidence BETWEEN 1 AND 5), CompletedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), UNIQUE(UserId,LessonId));
CREATE TABLE Attempts (Id int IDENTITY PRIMARY KEY, UserId int NOT NULL REFERENCES Users(Id), TopicId int NOT NULL REFERENCES Topics(Id), Score int NOT NULL, Total int NOT NULL CHECK(Total>0), AttemptedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Notes (Id int IDENTITY PRIMARY KEY, UserId int NOT NULL REFERENCES Users(Id), LessonId int NULL REFERENCES Lessons(Id), Title nvarchar(100) NOT NULL, Body nvarchar(3000) NOT NULL, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Flashcards (Id int IDENTITY PRIMARY KEY, UserId int NOT NULL REFERENCES Users(Id), TopicId int NULL REFERENCES Topics(Id), Front nvarchar(400) NOT NULL, Back nvarchar(400) NOT NULL, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Exercises (Id int IDENTITY PRIMARY KEY, LessonId int NOT NULL REFERENCES Lessons(Id), Prompt nvarchar(500) NOT NULL, Starter nvarchar(2000) NOT NULL, Answer nvarchar(200) NOT NULL, Explanation nvarchar(1000) NOT NULL, SortOrder int NOT NULL CHECK(SortOrder BETWEEN 1 AND 99));
CREATE TABLE PracticeAttempts (Id int IDENTITY PRIMARY KEY, UserId int NOT NULL REFERENCES Users(Id), ExerciseId int NOT NULL REFERENCES Exercises(Id), Correct bit NOT NULL, AttemptedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Reflections (Id int IDENTITY PRIMARY KEY, UserId int NOT NULL REFERENCES Users(Id), LessonId int NOT NULL REFERENCES Lessons(Id), Explanation nvarchar(1500) NOT NULL DEFAULT '', ExplainedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), UNIQUE(UserId,LessonId));
